<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue';
import {all,request} from '../Administration/api';
import SearchSelect from '../Workshop/components/SearchSelect.vue';
import {instant,localInstant} from '../Workshop/presentation';
import {registrationDate} from '../FleetAndDocuments/presentation';
import type {Part,Supplier,PurchaseRequest,PurchaseOrder} from './contracts';
const props=defineProps<{admin:boolean;busy:boolean;epoch:number}>();
const emit=defineEmits<{command:[title:string,path:string,body:Record<string,unknown>];error:[error:unknown]}>();
interface Need {id:string;description:string;quantity:string;is_effective:boolean;work_order_id:string}
const needs=ref<Need[]>([]),need=ref('');
const requests=ref<PurchaseRequest[]>([]),orders=ref<PurchaseOrder[]>([]),parts=ref<Part[]>([]),suppliers=ref<Supplier[]>([]);
const selected=ref<PurchaseRequest|null>(null),order=ref<PurchaseOrder|null>(null),mode=ref(''),reason=ref(''),supplier=ref(''),part=ref(''),quantity=ref(''),decision=ref('approved'),receivedAt=ref(localInstant()),loading=ref(false),search=ref('');
const quantities=ref<Record<string,string>>({});
const supplierOptions=computed(()=>suppliers.value.map(s=>({value:s.id,label:s.name}))),partOptions=computed(()=>parts.value.map(s=>({value:s.id,label:`${s.code} · ${s.description} · ${s.unit}`})));
const needOptions=computed(()=>needs.value.filter(n=>n.is_effective).map(n=>({value:n.id,label:`${n.description} · ${n.quantity} · Orden ${n.work_order_id}`})));
const filtered=computed(()=>requests.value.filter(r=>`${r.supplier.name} ${r.reason}`.toLowerCase().includes(search.value.toLowerCase())));
let generation=0;onBeforeUnmount(()=>generation++);
async function load():Promise<void>{const run=++generation;loading.value=true;try{const [r,o,l,n]=await Promise.all([all<PurchaseRequest>('/purchasing/requests'),all<PurchaseOrder>('/purchasing/orders'),request<{parts:Part[];suppliers:Supplier[]}>('/purchasing/lookups'),all<Need>('/workshop/material-needs?effective=1')]);if(run!==generation)return;needs.value=n;requests.value=r;orders.value=o;parts.value=l.parts;suppliers.value=l.suppliers;if(order.value)order.value=o.find(v=>v.id===order.value?.id)??null;if(selected.value)selected.value=r.find(v=>v.id===selected.value?.id)??null;}catch(e){if(run===generation)emit('error',e);}finally{if(run===generation)loading.value=false;}}
function begin(kind:string,r?:PurchaseRequest,o?:PurchaseOrder):void{mode.value=kind;selected.value=r??null;order.value=o??null;reason.value='';quantities.value={};receivedAt.value=localInstant();}
function submit():void{if(props.busy)return;if(mode.value==='request')emit('command','Registrar solicitud de compra','/purchasing/requests',{supplier_id:supplier.value,reason:reason.value,items:[{spare_part_id:part.value,quantity:quantity.value,...(need.value?{workshop_material_need_id:need.value}:{})}]});if(mode.value==='decision'&&selected.value)emit('command','Registrar decisión administrativa',`/purchasing/requests/${selected.value.id}/decisions`,{decision:decision.value,reason:reason.value});if(mode.value==='order'&&selected.value)emit('command','Registrar orden de compra','/purchasing/orders',{purchase_request_id:selected.value.id,reason:reason.value,items:selected.value.items.filter(i=>quantities.value[i.id]).map(i=>({purchase_request_item_id:i.id,quantity:quantities.value[i.id]}))});if(mode.value==='receipt'&&order.value)emit('command','Confirmar recepción física',`/purchasing/orders/${order.value.id}/receipts`,{received_at:instant(receivedAt.value),reason:reason.value,items:order.value.items.filter(i=>quantities.value[i.id]).map(i=>({purchase_order_item_id:i.id,quantity:quantities.value[i.id]}))});}
watch(()=>props.epoch,()=>{mode.value='';void load();});onMounted(load);
</script>
<template><section class="space-y-5"><p class="notice-info">La autorización no aumenta existencias. Solo una recepción física confirmada ingresa repuestos a bodega.</p><div class="flex flex-wrap gap-3"><button class="btn-primary" :disabled="busy||loading" @click="begin('request')">Registrar solicitud de compra</button><button class="btn-secondary" :disabled="busy||loading" @click="load">Actualizar compras</button><a v-if="admin" class="btn-secondary" href="/administracion/catalogos">Repuestos y proveedores</a></div><p v-if="loading" role="status">Consultando compras…</p>
<form v-if="mode" class="panel space-y-4" :aria-label="mode==='receipt'?'Recepción física':'Operación de compra'" @submit.prevent="submit"><h2 class="font-semibold">{{mode==='request'?'Nueva solicitud':mode==='decision'?'Decisión administrativa':mode==='order'?'Nueva orden de compra':'Recepción física parcial o completa'}}</h2><fieldset :disabled="busy||loading" class="space-y-3"><template v-if="mode==='request'"><SearchSelect v-model="supplier" label="Proveedor" :options="supplierOptions" required/><SearchSelect v-model="part" label="Repuesto" :options="partOptions" required/><SearchSelect v-model="need" label="Necesidad de Taller (opcional)" :options="needOptions"/><label>Cantidad solicitada<input aria-label="Cantidad solicitada" v-model="quantity" class="field" required inputmode="decimal"></label></template><template v-if="mode==='decision'"><p>{{selected?.supplier.name}} · {{selected?.reason}}</p><ul><li v-for="i in selected?.items" :key="i.id">{{i.code}} · {{i.description}} · {{i.quantity}} {{i.unit}}</li></ul><label>Decisión<select aria-label="Decisión" v-model="decision" class="field"><option value="approved">Aprobar</option><option value="rejected">Rechazar</option></select></label></template><template v-if="mode==='order'"><p>{{selected?.supplier.name}} · Solicitud {{selected?.id}}</p><label v-for="i in selected?.items" :key="i.id" class="block">{{i.code}} · {{i.description}} · Autorizado: {{i.quantity}} {{i.unit}}<input :aria-label="`Cantidad ordenada ${i.code}`" v-model="quantities[i.id]" class="field" inputmode="decimal" placeholder="Cantidad a ordenar"></label></template><template v-if="mode==='receipt'"><label>Fecha de recepción<input aria-label="Fecha de recepción" v-model="receivedAt" class="field" type="datetime-local" required></label><label v-for="i in order?.items" :key="i.id" class="block">{{i.code}} · {{i.description}} · Recibido: {{i.received_quantity}} · Pendiente: {{i.pending_quantity}} {{i.unit}}<input :aria-label="`Cantidad recibida ${i.code}`" v-model="quantities[i.id]" class="field" inputmode="decimal" placeholder="Cantidad físicamente recibida"></label><p>No registres cantidades pendientes como recibidas.</p></template><label class="block">Motivo y diferencias observadas<textarea aria-label="Motivo" v-model="reason" class="field" required maxlength="5000"/></label><button class="btn-primary">{{mode==='receipt'?'Confirmar recepción física':'Guardar operación'}}</button> <button type="button" class="btn-secondary" @click="mode=''">Cancelar</button></fieldset></form>
<section class="panel"><h2 class="font-semibold">Solicitudes de compra</h2><label>Buscar solicitudes<input v-model="search" aria-label="Buscar solicitudes" type="search" class="field"></label><div class="overflow-x-auto"><table class="data-table"><thead><tr><th>Proveedor</th><th>Motivo y repuestos</th><th>Decisión</th><th>Acciones</th></tr></thead><tbody><tr v-for="r in filtered" :key="r.id"><td>{{r.supplier.name}}</td><td>{{r.reason}}<ul><li v-for="i in r.items" :key="i.id">{{i.code}} · {{i.quantity}} {{i.unit}} <span v-if="i.workshop_material_need_id">· Necesidad Taller {{i.workshop_material_need_id}}</span></li></ul></td><td>{{r.decision?.decision??'Pendiente'}}</td><td><button v-if="admin&&!r.decision" class="btn-secondary" :disabled="busy||loading" @click="begin('decision',r)">Decidir solicitud</button><button v-if="r.decision?.decision==='approved'" class="btn-secondary" :disabled="busy||loading" @click="begin('order',r)">Generar orden de compra</button></td></tr></tbody></table></div></section>
<section class="panel"><h2 class="font-semibold">Órdenes y recepciones</h2><div v-for="o in orders" :key="o.id" class="border-b border-blue-200 py-4 space-y-2"><h3>{{o.supplier.name}} · Orden {{o.id}}</h3><p>{{o.reason}} · Solicitud {{o.purchase_request_id}}</p><ul><li v-for="i in o.items" :key="i.id">{{i.code}} · {{i.description}} · Autorizado {{i.authorized_quantity}} · Ordenado {{i.quantity}} · Recibido {{i.received_quantity}} · Pendiente {{i.pending_quantity}} {{i.unit}}</li></ul><button :disabled="busy||loading" class="btn-primary" @click="begin('receipt',undefined,o)">Registrar recepción física</button><details><summary>Historial de recepciones</summary><article v-for="r in o.receipts" :key="r.id"><p>{{registrationDate(r.received_at)}} · {{r.reason}}</p><ul><li v-for="i in r.items" :key="i.id">{{o.items.find(v=>v.id===i.purchase_order_item_id)?.code}}: {{i.quantity}}</li></ul></article></details></div><p v-if="!orders.length">Sin órdenes registradas.</p></section></section></template>
